func (this *Binance) fetchEventsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var allowUnscopedFetchEvents *bool = this.SafeBool(this.Options, "allowUnscopedFetchEvents", false)
	if allowUnscopedFetchEvents == nil || *allowUnscopedFetchEvents != true {
		this.RequireEventQuery(params)
	}
	var queries []any = ccxt.ArrayTyped(this.ParseSearchQueries(params))
	// binance has no tag taxonomy — resolve requested tags through the semantic search too
	var tags []any = ccxt.SafeListTyped(params, "tags")
	var tagsLength int = len(tags)
	var allQueries []any = []any{}
	for i := 0; i < len(queries); i++ {
		allQueries = append(allQueries, func() any {
			if i >= 0 && i < len(queries) {
				return ccxt.DerefScalar(queries[i])
			}
			return nil
		}())
	}
	for i := 0; i < tagsLength; i++ {
		allQueries = append(allQueries, func() any {
			if i >= 0 && i < len(tags) {
				return ccxt.DerefScalar(tags[i])
			}
			return nil
		}())
	}
	var allQueriesLength int = len(allQueries)
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"query", "queries"})
	// keys dropped before the client-side pass; a server-side sort also drops its own keys
	var postOmitKeys []any = []any{"tags", "l1Category", "l2Category"}
	var userLimit *int64 = this.SafeInteger(paramsOmitted, "limit")
	var fetchCap *int64 = this.SafeInteger(this.Options, "maxFetchEventsResults", 100)
	if userLimit != nil {
		fetchCap = userLimit
	}
	var rest map[string]any = this.OmitDict(paramsOmitted, []any{"status", "limit", "sort", "searchIn", "eventId", "slug", "tags", "l1Category", "l2Category"})
	var eventId *string = this.SafeString(paramsOmitted, "eventId")
	var l1Category *string = this.SafeString(paramsOmitted, "l1Category")
	var l2Category *string = this.SafeString(paramsOmitted, "l2Category")
	if this.Markets == nil {
		this.Markets = this.CreateSafeDictionary()
	}
	var rawTopics any = []any{}
	if allQueriesLength > 0 {

		rawTopics = (<-this.FetchEventsByQueryAsync(allQueries, fetchCap, rest))
		ccxt.PanicOnError(rawTopics)
	} else if eventId != nil {

		detail := (<-this.FetchRawTopicDetailAsync(eventId, rest))
		ccxt.PanicOnError(detail)
		rawTopics = []any{detail}
	} else {
		var listingRequest map[string]any = map[string]any{}
		if l1Category != nil {
			listingRequest["l1Category"] = l1Category
		}
		if l2Category != nil {
			listingRequest["l2Category"] = l2Category
		}
		var sortBy *string = this.SafeStringUpper2(paramsOmitted, "sortBy", "sort")
		if sortBy != nil {
			// map the unified sort values onto the server enum, one of RECOMMENDED,
			// VOLUME, PARTICIPANTS, CREATED_TIME or END_DATE — 'liquidity' has no
			// server-side equivalent and stays in params so the base
			// applyEventFetchParams sorts it client-side instead
			if sortBy != nil && *sortBy == "NEWEST" {
				sortBy = ccxt.SafeStringPtr("CREATED_TIME")
			} else if sortBy != nil && *sortBy == "LIQUIDITY" {
				sortBy = nil
			}
			if sortBy != nil {
				listingRequest["sortBy"] = sortBy
				postOmitKeys = append(postOmitKeys, "sort")
				postOmitKeys = append(postOmitKeys, "sortBy")
			}
		}

		listed := (<-this.FetchRawTopicsAsync(fetchCap, this.Extend(listingRequest, rest)))
		ccxt.PanicOnError(listed)

		rawTopics = (<-this.CompleteRawTopicsAsync(listed))
		ccxt.PanicOnError(rawTopics)
	}
	var rawTopicsLength int = ccxt.GetArrayLength(rawTopics)
	var result []any = []any{}
	for i := 0; i < rawTopicsLength; i++ {
		var parsedEvent any = this.ParseEvent(ccxt.GetValue(rawTopics, i))
		result = append(result, parsedEvent)
		var parsedMarkets []any = ccxt.SafeListTyped(parsedEvent, "markets")
		var parsedMarketsLength int = len(parsedMarkets)
		for mi := 0; mi < parsedMarketsLength; mi++ {
			var m any = func() any {
				if mi >= 0 && mi < len(parsedMarkets) {
					return ccxt.DerefScalar(parsedMarkets[mi])
				}
				return nil
			}()
			// prediction market rows are keyed by the unified 'market' handle
			var handle *string = this.SafeString(m, "market")
			if handle != nil {
				ccxt.AddElementToObject(this.Markets, handle, m)
			}
		}
	}
	this.PopulateOutcomes()
	// scoping already happened server-side: the tag filter needs an event-level tags field
	// binance topics lack, and the query filter would drop semantic-search matches whose
	// title uses different words than the query
	var postParams map[string]any = this.OmitDict(paramsOmitted, postOmitKeys)

	ch <- this.ApplyEventFetchParams(result, postParams, []any{})
	return nil
}

