/**
 * @ignore
 * @method
 * @name binance#parsePredictionTicker
 * @description parses a last-trade-price response into a unified ticker object; the venue quotes the market's primary (YES) token, so a NO outcome mirrors as 1 - price
 * @param {object} raw the raw last-trade-price object
 * @param {object} [market] the outcome object the ticker belongs to
 * @returns {object} a [ticker structure](https://docs.ccxt.com/#/?id=ticker-structure)
 */
func (this *Binance) ParsePredictionTicker(raw any, optionalArgs ...any) any {
	//
	//     { "marketId": 5567895, "lastTradePrice": "0.52" }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var marketAny any = market
	var outcomeObj map[string]any = this.SafeOutcome(this.SafeString(marketAny, "outcome"), marketAny)
	// the venue quotes the market's primary token (outcome index 0, e.g. YES or UP),
	// any other outcome of a binary market mirrors as 1 - price
	var outcomeInfo map[string]any = ccxt.SafeMapTyped(outcomeObj, "info")
	var outcomeIndex *string = this.SafeString(outcomeInfo, "index")
	var isMirrored bool = false
	if outcomeIndex != nil {
		isMirrored = (outcomeIndex == nil || *outcomeIndex != "0")
	} else {
		var label *string = this.SafeStringUpper(outcomeObj, "label", "YES")
		isMirrored = (label != nil && *label == "NO") || (label != nil && *label == "DOWN")
	}
	var lastString *string = this.SafeString(raw, "lastTradePrice")
	var last *float64 = nil
	if lastString != nil {
		if isMirrored {
			last = ccxt.Float64PtrTyped(this.ParseNumber(ccxt.Precise.StringSub("1", lastString)))
		} else {
			last = ccxt.Float64PtrTyped(this.ParseNumber(lastString))
		}
	}
	return this.SafePredictionTicker(map[string]any{
		"outcome":       this.SafeString(outcomeObj, "outcome"),
		"outcomeId":     this.SafeString2(outcomeObj, "outcomeId", "id"),
		"label":         this.SafeString(outcomeObj, "label"),
		"market":        this.SafeString(outcomeObj, "market"),
		"timestamp":     nil,
		"datetime":      nil,
		"high":          nil,
		"low":           nil,
		"bid":           nil,
		"bidVolume":     nil,
		"ask":           nil,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    nil,
		"quoteVolume":   nil,
		"info":          raw,
	}, market)
}

/**
 * @method
 * @name binance#fetchTickers
 * @description fetches last trade prices for multiple outcomes, one request per distinct underlying market
 * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/market-data#query-last-trade-price
 * @param {string[]} outcomes unified outcomes — required: the venue has no all-tickers endpoint
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of prediction [ticker structures](https://docs.ccxt.com/#/?id=ticker-structure)
 */
func (this *Binance) FetchTickersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Binance) fetchTickersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var outcomes []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = outcomes
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if outcomes == nil {
		panic(ccxt.ArgumentsRequired(this.Id + " fetchTickers() requires an outcomes argument — the venue has no all-tickers endpoint; pass the outcome handles to fetch (discover them via fetchEvents ())"))
	}

	ccxt.PanicOnError((<-this.LoadOutcomesAsync(outcomes)))
	var responsesByMarketId map[string]any = map[string]any{}
	var result map[string]any = map[string]any{}
	var outcomesLength int = len(outcomes)
	for i := 0; i < outcomesLength; i++ {
		var outcomeObj map[string]any = this.Outcome(ccxt.GetValue(outcomes, i))
		var info map[string]any = ccxt.SafeMapTyped(outcomeObj, "info")
		var marketId *string = this.SafeString(info, "marketId")
		if marketId == nil {
			continue
		}
		var response any = this.SafeDict(responsesByMarketId, marketId)
		if ccxt.IsEqual(response, nil) {
			var request map[string]any = map[string]any{
				"marketId": marketId,
			}

			response = (<-this.SapiPrivateGetOrderBookLastTradePrice(this.Extend(request, params))).Raw
			ccxt.PanicOnError(response)
			ccxt.AddElementToObject(responsesByMarketId, marketId, response)
		}
		var ticker any = this.ParsePredictionTicker(response, outcomeObj)
		var symbolKey *string = this.SafeString(ticker, "outcome", ccxt.GetValue(outcomes, i))
		ccxt.AddElementToObject(result, symbolKey, ticker)
	}

	ch <- result
	return nil
}

