func (this *Binance) fetchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	typeVar, paramsType := this.HandleOptionStringAndParams(params, "fetchBalance", "type", "SPOT")

	response := (<-this.SapiPrivateGetBalancePaymentOptions(paramsType)).Raw
	ccxt.PanicOnError(response)
	//
	// {
	//     "items": [
	//         {
	//             "accountType": "SPOT",
	//             "availableBalanceDisplay": "1000.00",
	//             "enabled": true
	//         }
	//     ]
	// }
	//
	var result map[string]any = map[string]any{
		"info": response,
	}
	var balances []any = ccxt.SafeListTyped(response, "items")
	for i := 0; i < len(balances); i++ {
		var balance map[string]any = ccxt.SafeMapTyped(balances, i)
		var accountType *string = this.SafeString(balance, "accountType")
		if ccxt.IsEqual(accountType, typeVar) {
			var free *string = this.SafeString(balance, "availableBalanceDisplay")
			var account map[string]any = this.Account()
			account["free"] = free
			result["USDT"] = account
		}
	}

	ch <- this.SafeBalance(result)
	return nil
}

/**
 * @ignore
 * @method
 * @name binance#parsePredictionOrder
 * @description parses a raw binance prediction order object into a unified order object
 * @param {object} order the raw order object
 * @param {object} [outcomeObj] the ourtome the order belongs to
 * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
 */
func (this *Binance) ParsePredictionOrder(order any, optionalArgs ...any) any {
	//
	// {
	//     "orderId": "54124",
	//     "vendorOrderId": "0x1234abcd...",
	//     "vendor": "PREDICT_FUN",
	//     "marketTopicId": 4229564,
	//     "slug": "btc-price-1h-up-or-down",
	//     "marketTopicTitle": "BTC Price 1h Up or Down?",
	//     "marketId": 5567895,
	//     "marketTitle": "UP",
	//     "outcome": "YES",
	//     "outcomeIndex": 0,
	//     "status": "OPENING",
	//     "side": "BUY",
	//     "orderType": "LIMIT",
	//     "createTime": 1748131500000,
	//     "modifyTime": 1748131500000,
	//     "makerUsdtAmount": "1.00",
	//     "makerShareQty": "2000.00",
	//     "filledUsdtAmount": "0.00",
	//     "filledShareQty": "0.00",
	//     "fillPercentage": "0.00",
	//     "price": "0.50",
	//     "marketProviderFee": "0.02",
	//     "networkFee": "0.000001"
	// }
	//
	var outcomeObj map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = outcomeObj
	var status any = this.ParseOrderStatus(this.SafeString(order, "status"))
	var outcomeObjResolved any = outcomeObj
	if ccxt.IsEqual(outcomeObjResolved, nil) {
		var marketId *string = this.SafeString(order, "marketId")
		var outcome *string = this.SafeStringUpper(order, "outcome")
		var market map[string]any = this.SafeMarket(marketId)
		var outcomeName any = ccxt.DerefScalar(this.SafeString(market, "market"))
		if ccxt.IsEqual(outcomeName, nil) {
			outcomeName = marketId
		}
		outcomeName = ccxt.Add(outcomeName, ccxt.Add(":", outcome))
		outcomeObjResolved = this.SafeOutcome(outcomeName)
	}
	var side *string = this.SafeStringLower(order, "side")
	var timestamp *int64 = this.SafeInteger(order, "createTime")
	return this.SafePredictionOrder(map[string]any{
		"id":                 this.SafeString(order, "orderId"),
		"clientOrderId":      nil,
		"info":               order,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             status,
		"outcome":            this.SafeString(outcomeObjResolved, "outcome"),
		"outcomeId":          this.SafeString(outcomeObjResolved, "id"),
		"label":              this.SafeString(outcomeObjResolved, "label"),
		"market":             this.SafeString(outcomeObjResolved, "market"),
		"type":               this.SafeStringLower(order, "orderType"),
		"timeInForce":        nil,
		"postOnly":           nil,
		"reduceOnly":         nil,
		"side":               side,
		"price":              this.SafeNumber(order, "price"),
		"triggerPrice":       nil,
		"amount":             nil,
		"cost":               nil,
		"average":            nil,
		"filled":             nil,
		"remaining":          nil,
		"fee":                nil,
		"trades":             []any{},
	}, outcomeObjResolved)
}
func (this *Binance) ParseOrderStatus(status *string) any {
	var statuses map[string]any = map[string]any{
		"OPENING": "open",
		"FILLED":  "closed",
	}
	if status == nil {
		return nil
	}
	if strings.HasSuffix(*status, "Rejected") {
		return "rejected"
	}
	if strings.HasSuffix(*status, "Canceled") {
		return "canceled"
	}
	return this.SafeString(statuses, status, status)
}

