func (this *Binance) fetchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var outcomes []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = outcomes
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	ccxt.PanicOnError((<-this.LoadOutcomesAsync()))
	var requestedOutcomeSymbols map[string]any = map[string]any{}
	if outcomes != nil {
		for i := 0; i < len(outcomes); i++ {
			var requested *string = ccxt.SafeStringPtr(ccxt.GetValue(outcomes, i))
			var requestedOutcomeObj map[string]any = this.SafeOutcome(requested)
			var requestedOutcome *string = this.SafeString(requestedOutcomeObj, "outcome", requested)
			ccxt.AddElementToObject(requestedOutcomeSymbols, requestedOutcome, true)
		}
	}

	wallet := (<-this.FetchWalletAsync("fetchPositions", params))
	ccxt.PanicOnError(wallet)
	var request map[string]any = map[string]any{
		"walletAddress": ccxt.GetValue(wallet, "walletAddress"),
	}

	var response map[string]any = (<-this.SapiPrivateGetPositionList(this.Extend(request, params))).Checked()
	//
	// {
	//     "summary": {
	//         "totalValue": "1523.45",
	//         "positionValue": "523.45",
	//         "walletBalance": "1000.00",
	//         "totalClaimableAmount": "50.00",
	//         "todayRealizedPnl": "15.30",
	//         "todayRealizedPnlPercent": "3.10",
	//         "todayTotalCost": "493.55"
	//     },
	//     "counts": {
	//         "ongoingCount": 3,
	//         "endedCount": 12,
	//         "pendingClaimCount": 1
	//     },
	//     "positions": [
	//         {
	//             "positionId": 1001,
	//             "vendor": "PREDICT_FUN",
	//             "chainId": "56",
	//             "tokenId": "112233",
	//             "collateralSymbol": "USDT",
	//             "topicType": "FLAT",
	//             "marketTopicId": 4229564,
	//             "marketId": 5567895,
	//             "marketTopicTitle": "BTC Price 1h Up or Down?",
	//             "marketTitle": "UP",
	//             "outcomeName": "YES",
	//             "outcomeIndex": 0,
	//             "shares": "1923.07",
	//             "avgPrice": "0.52",
	//             "totalCost": "1.00",
	//             "value": "1.06",
	//             "currentPrice": "0.55",
	//             "toWin": "1923.07",
	//             "positionStatus": "OPEN",
	//             "canClaim": false,
	//             "endDate": 1748134800000,
	//             "unrealizedPnl": "0.06",
	//             "unrealizedPnlPercent": "6.00",
	//             "realizedPnl": "0.00",
	//             "pnl": "0.06",
	//             "createdTime": 1748131500000,
	//             "updatedTime": 1748132000000
	//         }
	//     ]
	// }
	//
	var data []any = ccxt.SafeListTypedDefault(response, "positions", []any{})
	var positions any = this.ParsePredictionPositions(data)
	if outcomes == nil {

		ch <- positions
		return nil
	}
	var filtered []any = []any{}
	var positionsLength int = ccxt.GetArrayLength(positions)
	for i := 0; i < positionsLength; i++ {
		var position any = ccxt.GetValue(positions, i)
		var positionOutcome *string = this.SafeString(position, "outcome")
		if (positionOutcome != nil) && (func() bool {
			if positionOutcome == nil {
				return false
			}
			_, ok := requestedOutcomeSymbols[*positionOutcome]
			return ok
		}()) {
			filtered = append(filtered, position)
		}
	}

	ch <- filtered
	return nil
}

