/**
 * @ignore
 * @method
 * @name binance#parsePredictionPosition
 * @description parses a spot balance entry for an outcome token into a unified position object
 * @param {object} position the raw balance entry
 * @param {object} [outcomeObj] the ourtome the position belongs to
 * @returns {object} a [prediction position structure](https://docs.ccxt.com/#/?id=prediction-position-structure)
 */
func (this *Binance) ParsePredictionPosition(position any, optionalArgs ...any) any {
	var outcomeObj map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = outcomeObj
	var outcomeObjResolved any = outcomeObj
	if ccxt.IsEqual(outcomeObjResolved, nil) {
		var marketId *string = this.SafeString(position, "marketId")
		var outcome *string = this.SafeStringUpper(position, "outcomeName")
		var market map[string]any = this.SafeMarket(marketId)
		var outcomeName any = ccxt.DerefScalar(this.SafeString(market, "market"))
		if ccxt.IsEqual(outcomeName, nil) {
			outcomeName = marketId
		}
		outcomeName = ccxt.Add(outcomeName, ccxt.Add(":", outcome))
		outcomeObjResolved = this.SafeOutcome(outcomeName)
	}
	var timestamp *int64 = this.SafeInteger(position, "createdTime")
	var totalCost *float64 = ccxt.Float64PtrTyped(this.ParseNumber(this.SafeString(position, "totalCost")))
	return this.SafePredictionPosition(map[string]any{
		"id":                          this.SafeInteger(position, "positionId"),
		"outcome":                     this.SafeString(outcomeObjResolved, "outcome"),
		"outcomeId":                   this.SafeString2(outcomeObjResolved, "outcomeId", "id"),
		"market":                      this.SafeString(outcomeObjResolved, "market"),
		"timestamp":                   timestamp,
		"datetime":                    this.Iso8601(timestamp),
		"isolated":                    false,
		"hedged":                      nil,
		"side":                        "long",
		"contracts":                   nil,
		"contractSize":                this.ParseNumber(this.SafeString(position, "shares")),
		"entryPrice":                  this.ParseNumber(this.SafeString(position, "avgPrice")),
		"markPrice":                   nil,
		"notional":                    this.ParseNumber(this.SafeString(position, "value")),
		"leverage":                    nil,
		"collateral":                  totalCost,
		"initialMargin":               totalCost,
		"maintenanceMargin":           nil,
		"initialMarginPercentage":     nil,
		"maintenanceMarginPercentage": nil,
		"unrealizedPnl":               this.ParseNumber(this.SafeString(position, "unrealizedPnl")),
		"realizedPnl":                 this.ParseNumber(this.SafeString(position, "realizedPnl")),
		"liquidationPrice":            nil,
		"marginRatio":                 nil,
		"marginMode":                  "cross",
		"percentage":                  this.ParseNumber(this.SafeString(position, "unrealizedPnlPercent")),
		"info":                        position,
	})
}

